  ('43855dcc-2790-4519-8f4d-de610963eee1','11111111-1111-1111-1111-111111111112','Según el artículo 20, apartado 2, ¿cuál de las siguientes afirmaciones es correcta?','El ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa.', now(), now()),
